    static associate(models) {
      Cart.belongsTo(models.User, { foreignKey: "userId", as: "user" });
      Cart.hasMany(models.CartItem, { foreignKey: "cartId", as: "cartItems" });
    }
  }
  Cart.init({
    userId: DataTypes.INTEGER,
  }, {
    sequelize,
    modelName: 'Cart',
  });

  return Cart;
};

